import json
import os
import sys
from types import SimpleNamespace

import pytest

from browser_use.skill_cli import main as mainmod


class ParserStub:
    def __init__(self, args_ns):
        self._ns = args_ns
        self.help_called = False

    def parse_args(self):
        # Ensure many commonly accessed attributes exist with defaults to avoid AttributeError
        defaults = {
            "connect": False,
            "json": False,
            "headed": False,
            "profile": None,
            "cdp_url": None,
            "session": None,
            "cloud_args": [],
            "profile_args": [],
            "yes": False,
            "config_command": None,
            "key": None,
            "value": None,
            "port_or_subcommand": None,
            "port_arg": None,
            "all": False,
            "record_command": None,
            "path": None,
        }
        for k, v in defaults.items():
            if not hasattr(self._ns, k):
                setattr(self._ns, k, v)
        return self._ns

    def print_help(self):
        self.help_called = True
        print("help")


def make_parser(ns):
    return ParserStub(ns)


def test_no_command_returns_zero_and_prints_help(monkeypatch, capsys):
    ns = SimpleNamespace(command=None)
    monkeypatch.setattr(mainmod, "build_parser", lambda: make_parser(ns))
    # Run
    ret = mainmod.main()
    captured = capsys.readouterr()
    assert ret == 0
    assert "help" in captured.out


def test_invalid_session_name(monkeypatch, capsys):
    # session invalid characters -> early return 1
    ns = SimpleNamespace(
        command="anything",
        session="bad name!",
        connect=False,
        cdp_url=None,
        profile=None,
        headed=False,
        json=False,
    )
    monkeypatch.setattr(mainmod, "build_parser", lambda: make_parser(ns))
    ret = mainmod.main()
    out = capsys.readouterr()
    assert ret == 1
    assert "Invalid session name" in out.err


def test_cloud_connect_intercept(monkeypatch):
    # cloud connect should call _handle_cloud_connect
    ns = SimpleNamespace(command="cloud", cloud_args=["connect", "foo"], session=None)
    monkeypatch.setattr(mainmod, "build_parser", lambda: make_parser(ns))
    called = {}

    def fake_handle_cloud_connect(rest, args_obj, session):
        called["args"] = (rest, args_obj, session)
        return 42

    monkeypatch.setattr(mainmod, "_handle_cloud_connect", fake_handle_cloud_connect)
    ret = mainmod.main()
    assert ret == 42
    assert called["args"][0] == ["foo"]


