def test_setup_json_and_error(monkeypatch, capsys):
    # First: json output
    ns = SimpleNamespace(command="setup", yes=False, json=True, session=None)
    monkeypatch.setattr(mainmod, "build_parser", lambda: make_parser(ns))
    monkeypatch.setattr("browser_use.skill_cli.commands.setup.handle", lambda yes=False: {"ok": True})
    ret = mainmod.main()
    out = capsys.readouterr()
    assert ret == 0
    assert json.loads(out.out) == {"ok": True}

    # Second: error path
    ns2 = SimpleNamespace(command="setup", yes=False, json=False, session=None)
    monkeypatch.setattr(mainmod, "build_parser", lambda: make_parser(ns2))
    monkeypatch.setattr("browser_use.skill_cli.commands.setup", SimpleNamespace(handle=lambda yes=False: {"error": "bad"}))
    ret2 = mainmod.main()
    captured = capsys.readouterr()
    assert ret2 == 1
    assert "Error: bad" in captured.err


def test_doctor_prints_checks_and_config(monkeypatch, capsys):
    # Simulate asyncio.run returning a diagnostics dict with various statuses
    ns = SimpleNamespace(command="doctor", json=False, session=None, headed=False, profile=None, cdp_url=None)
    monkeypatch.setattr(mainmod, "build_parser", lambda: make_parser(ns))

    diag = {
        "checks": {
            "one": {"status": "ok", "message": "fine"},
            "two": {"status": "warning", "message": "be careful", "note": "note1"},
            "three": {"status": "missing", "message": "install", "fix": "do this"},
            "four": {"status": "bad", "message": "broken"},
        },
        "status": "unhealthy",
        "summary": "problems",
    }

    monkeypatch.setattr(mainmod.asyncio, "run", lambda coro: diag)
    monkeypatch.setattr("browser_use.skill_cli.config.CLI_DOCS_URL", "http://docs")
    # get_config_display returns entries with set/unset and sensitive flags
    monkeypatch.setattr("browser_use.skill_cli.config.get_config_display", lambda: [
        {"is_set": True, "sensitive": True, "key": "k1", "value": "secret"},
        {"is_set": False, "sensitive": False, "key": "k2", "value": None},
    ])
    # monkeypatch home dir used in printing
    monkeypatch.setattr(mainmod, "_get_home_dir", lambda: mainmod.Path("/home/user"))
    ret = mainmod.main()
    captured = capsys.readouterr()
    assert ret == 0
    # check that diagnostics and config docs printed
    assert "Diagnostics:" in captured.out
    assert "Docs: http://docs" in captured.out
    # ensure warnings printed
    assert "⚠" in captured.out or "problems" in captured.out


def test_config_set_get_unset_list(monkeypatch, capsys):
    # set success
    ns = SimpleNamespace(command="config", config_command="set", key="k", value="v", session=None)
    monkeypatch.setattr(mainmod, "build_parser", lambda: make_parser(ns))
    monkeypatch.setattr("browser_use.skill_cli.config.set_config_value", lambda k, v: None)
    ret = mainmod.main()
    out = capsys.readouterr()
    assert ret == 0
    assert "k = v" in out.out

    # set error
    ns2 = SimpleNamespace(command="config", config_command="set", key="k", value="v", session=None)
    monkeypatch.setattr(mainmod, "build_parser", lambda: make_parser(ns2))
    def raise_val(k, v):
        raise ValueError("nope")
    monkeypatch.setattr("browser_use.skill_cli.config.set_config_value", raise_val)
    ret2 = mainmod.main()
    captured = capsys.readouterr()
    assert ret2 == 1
    assert "Error: nope" in captured.err

    # get not set
    ns3 = SimpleNamespace(command="config", config_command="get", key="missing", session=None)
    monkeypatch.setattr(mainmod, "build_parser", lambda: make_parser(ns3))
    monkeypatch.setattr("browser_use.skill_cli.config.get_config_value", lambda k: None)
    ret3 = mainmod.main()
    cap = capsys.readouterr()
    assert ret3 == 0
    assert "missing: not set" in cap.err

    # unset error
    ns4 = SimpleNamespace(command="config", config_command="unset", key="k", session=None)
    monkeypatch.setattr(mainmod, "build_parser", lambda: make_parser(ns4))
    def raise_unset(k):
        raise ValueError("unset-error")
    monkeypatch.setattr("browser_use.skill_cli.config.unset_config_value", raise_unset)
    ret4 = mainmod.main()
    cap = capsys.readouterr()
    assert ret4 == 1
    assert "Error: unset-error" in cap.err

    # list
    ns5 = SimpleNamespace(command="config", config_command="list", session=None)
    monkeypatch.setattr(mainmod, "build_parser", lambda: make_parser(ns5))
    monkeypatch.setattr("browser_use.skill_cli.config.get_config_display", lambda: [
        {"is_set": True, "sensitive": False, "key": "a", "value": "val"},
        {"is_set": False, "sensitive": False, "key": "b", "value": ""},
    ])
    monkeypatch.setattr("browser_use.skill_cli.config.CLI_DOCS_URL", "http://docs")
    monkeypatch.setattr(mainmod, "_get_home_dir", lambda: mainmod.Path("/home/user"))
    ret5 = mainmod.main()
    cap = capsys.readouterr()
    assert ret5 == 0
    assert "Config (/home/user/config.json):" in cap.out
    assert "Docs: http://docs" in cap.out


def test_tunnel_branches(monkeypatch, capsys):
    # pos None -> usage and return 0
    ns = SimpleNamespace(command="tunnel", port_or_subcommand=None, json=False, session=None)
    monkeypatch.setattr(mainmod, "build_parser", lambda: make_parser(ns))
    ret = mainmod.main()
    cap = capsys.readouterr()
    assert ret == 0
    assert "Usage: browser-use tunnel" in (cap.err + cap.out)

    # pos == 'list' with tunnels empty -> prints No active tunnels
    class TunnelMod:
        @staticmethod
        def list_tunnels():
            return {"tunnels": []}
    monkeypatch.setattr(mainmod, "build_parser", lambda: make_parser(SimpleNamespace(command="tunnel", port_or_subcommand="list", json=False, session=None)))
    monkeypatch.setattr("browser_use.skill_cli.tunnel", TunnelMod)
    ret2 = mainmod.main()
    cap = capsys.readouterr()
    assert ret2 == 0
    assert "No active tunnels" in cap.out

    # pos == 'stop' with missing args -> prints usage and returns 1
    ns3 = SimpleNamespace(command="tunnel", port_or_subcommand="stop", port_arg=None, all=False, json=False, session=None)
    monkeypatch.setattr(mainmod, "build_parser", lambda: make_parser(ns3))
    monkeypatch.setattr("browser_use.skill_cli.tunnel", TunnelMod)
    ret3 = mainmod.main()
    cap = capsys.readouterr()
    assert ret3 == 1
    assert "Usage: browser-use tunnel stop" in cap.err

    # pos is numeric -> start_tunnel called and prints url
    class TunnelMod2:
        @staticmethod
        def start_tunnel(port):
            return {"url": f"http://t{port}", "existing": True}
    monkeypatch.setattr(mainmod, "build_parser", lambda: make_parser(SimpleNamespace(command="tunnel", port_or_subcommand="123", json=False, session=None)))
    monkeypatch.setattr("browser_use.skill_cli.tunnel", TunnelMod2)
    # asyncio.run invoked inside; monkeypatch to just call function directly for deterministic behavior
    monkeypatch.setattr(mainmod.asyncio, "run", lambda coro: TunnelMod2.start_tunnel(123))
    ret4 = mainmod.main()
    cap = capsys.readouterr()
    assert ret4 == 0
    assert "url: http://t123 (existing)" in cap.out


def test_close_variants(monkeypatch, capsys):
    # close with all -> calls _handle_close_all
    ns = SimpleNamespace(command="close", all=True, json=False, session=None)
    monkeypatch.setattr(mainmod, "build_parser", lambda: make_parser(ns))
    monkeypatch.setattr(mainmod, "_handle_close_all", lambda args: 13)
    ret = mainmod.main()
    assert ret == 13

    # close with json True -> prints json response
    ns2 = SimpleNamespace(command="close", all=False, json=True, session=None)
    monkeypatch.setattr(mainmod, "build_parser", lambda: make_parser(ns2))
    monkeypatch.setattr(mainmod, "_close_session", lambda session: True)
    ret2 = mainmod.main()
    cap = capsys.readouterr()
    assert ret2 == 0
    assert '"shutdown": true' in cap.out

    # close with closed True prints Browser closed
    ns3 = SimpleNamespace(command="close", all=False, json=False, session=None)
    monkeypatch.setattr(mainmod, "build_parser", lambda: make_parser(ns3))
    monkeypatch.setattr(mainmod, "_close_session", lambda session: True)
    # probe not called in this branch
    ret3 = mainmod.main()
    cap = capsys.readouterr()
    assert ret3 == 0
    assert "Browser closed" in cap.out

    # close with closed is False and pid_alive True -> prints Warning
    class Probe:
        pid_alive = True
    monkeypatch.setattr(mainmod, "build_parser", lambda: make_parser(SimpleNamespace(command="close", all=False, json=False, session="s1")))
    monkeypatch.setattr(mainmod, "_close_session", lambda session: False)
    monkeypatch.setattr(mainmod, "_probe_session", lambda s: Probe())
    ret4 = mainmod.main()
    cap = capsys.readouterr()
    assert ret4 == 0
    assert "Warning: daemon may still be shutting down" in cap.err


def test_connect_and_mutual_exclusive(monkeypatch, capsys):
    # --connect deprecation True
    ns = SimpleNamespace(command="anything", connect=True, session=None, cdp_url=None, profile=None, headed=False, json=False)
    monkeypatch.setattr(mainmod, "build_parser", lambda: make_parser(ns))
    ret = mainmod.main()
    cap = capsys.readouterr()
    assert ret == 1
    assert "Note: --connect has been replaced." in cap.err

    # connect command with discover raising -> returns 1
    def bad_discover():
        raise RuntimeError("no chrome")
    ns2 = SimpleNamespace(command="connect", headed=False, json=False, session=None, cdp_url=None, profile=None, connect=False)
    monkeypatch.setattr(mainmod, "build_parser", lambda: make_parser(ns2))
    monkeypatch.setattr("browser_use.skill_cli.utils.discover_chrome_cdp_url", bad_discover)
    ret2 = mainmod.main()
    cap = capsys.readouterr()
    assert ret2 == 1
    assert "Error: no chrome" in cap.err

    # connect success and response success True with cdp_url
    ns3 = SimpleNamespace(command="connect", headed=True, json=False, session="sess", cdp_url=None, profile=None, connect=False)
    monkeypatch.setattr(mainmod, "build_parser", lambda: make_parser(ns3))
    monkeypatch.setattr("browser_use.skill_cli.utils.discover_chrome_cdp_url", lambda: "cdp://1")
    monkeypatch.setattr(mainmod, "ensure_daemon", lambda headed, profile, cdp_url, session, explicit_config: None)
    monkeypatch.setattr(mainmod, "send_command", lambda cmd, params, session=None: {"success": True, "data": {"status": "ok", "cdp_url": "cdp://1"}})
    ret3 = mainmod.main()
    cap = capsys.readouterr()
    assert ret3 == 0
    assert "status: ok" in cap.out
    assert "cdp_url: cdp://1" in cap.out

    # mutual exclusivity: both cdp_url and profile set -> returns 1
    ns4 = SimpleNamespace(command="anything", cdp_url="x", profile="p", session=None, connect=False, headed=False, json=False)
    monkeypatch.setattr(mainmod, "build_parser", lambda: make_parser(ns4))
    ret4 = mainmod.main()
    assert ret4 == 1


def test_send_command_and_response_rendering(monkeypatch, capsys, tmp_path):
    # Test params resolving for upload and record start path, and printing of various data types
    # Prepare args for 'upload' with path
    p = tmp_path / "file.txt"
    p.write_text("content")
    ns = SimpleNamespace(command="upload", path=str(p), profile=None, headed=False, json=False, cdp_url=None, session=None, connect=False)
    monkeypatch.setattr(mainmod, "build_parser", lambda: make_parser(ns))
    # patch migrations and daemon ensure
    monkeypatch.setattr(mainmod, "_migrate_legacy_files", lambda: None)
    monkeypatch.setattr(mainmod, "ensure_daemon", lambda *a, **kw: None)
    # send_command returns dict with data dict with various keys
    long_screenshot = "x" * 200
    data_dict = {
        "_internal": "skip me",
        "screenshot": long_screenshot,
        "title": "MyTitle",
    }
    monkeypatch.setattr(mainmod, "send_command", lambda cmd, params, session=None: {"success": True, "data": data_dict})
    ret = mainmod.main()
    cap = capsys.readouterr()
    assert ret == 0
    # screenshot printed as bytes summary, internal skipped, title printed
    assert "screenshot: <200 bytes>" in cap.out
    assert "title: MyTitle" in cap.out
    assert "_internal" not in cap.out

    # Now test when data is raw text dict with _raw_text
    ns2 = SimpleNamespace(command="foo", profile=None, headed=False, json=False, cdp_url=None, session=None, connect=False)
    monkeypatch.setattr(mainmod, "build_parser", lambda: make_parser(ns2))
    monkeypatch.setattr(mainmod, "send_command", lambda cmd, params, session=None: {"success": True, "data": {"_raw_text": "RAW"}})
    monkeypatch.setattr(mainmod, "_migrate_legacy_files", lambda: None)
    monkeypatch.setattr(mainmod, "ensure_daemon", lambda *a, **kw: None)
    ret2 = mainmod.main()
    cap2 = capsys.readouterr()
    assert ret2 == 0
    assert "RAW" in cap2.out

    # When data is str
    monkeypatch.setattr(mainmod, "build_parser", lambda: make_parser(SimpleNamespace(command="bar", profile=None, headed=False, json=False, cdp_url=None, session=None, connect=False)))
    monkeypatch.setattr(mainmod, "send_command", lambda cmd, params, session=None: {"success": True, "data": "SOME TEXT"})
    ret3 = mainmod.main()
    cap3 = capsys.readouterr()
    assert ret3 == 0
    assert "SOME TEXT" in cap3.out

    # When response indicates error
    monkeypatch.setattr(mainmod, "build_parser", lambda: make_parser(SimpleNamespace(command="bar", profile=None, headed=False, json=False, cdp_url=None, session=None, connect=False)))
    monkeypatch.setattr(mainmod, "send_command", lambda cmd, params, session=None: {"success": False, "error": "badness"})
    ret4 = mainmod.main()
    cap4 = capsys.readouterr()
    assert ret4 == 1
    assert "Error: badness" in cap4.err
